def bfs(g):
    h,w=len(g),len(g[0]); dist=[[9]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==1: dist[i][j]=0
    q=deque((i,j) for i in range(h) for j in range(w) if g[i][j]==1)
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==0 and dist[a][b]==9:
                dist[a][b]=dist[i][j]+1; q.append((a,b))
    return dist
